+// AllSelectable reports whether every field is declared selectable for the
+// kind. A nil registry, an unknown kind, or any undeclared field returns false,
+// so a caller deciding whether the index can answer a filter falls back to the
+// store rather than asking the index for a field it never mapped.
+func (r *SearchFieldsRegistry) AllSelectable(key LowerGroupResource, fields []string) bool {
+	if r == nil {
+		return false
+	}
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+	declared := r.selectableFields[key]
+	for _, f := range fields {
+		if !slices.Contains(declared, f) {
+			return false
+		}
+	}
+	return true
+}
